CREATE TABLE IF NOT EXISTS sports(id BIGSERIAL PRIMARY KEY,code VARCHAR(40) UNIQUE NOT NULL,name VARCHAR(100) NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS leagues(id BIGSERIAL PRIMARY KEY,sport_id BIGINT NOT NULL REFERENCES sports(id),provider_league_id VARCHAR(100),name VARCHAR(200) NOT NULL,country VARCHAR(100),logo_url TEXT,coverage JSONB NOT NULL DEFAULT '{}'::jsonb,UNIQUE(sport_id,provider_league_id));
CREATE TABLE IF NOT EXISTS seasons(id BIGSERIAL PRIMARY KEY,league_id BIGINT NOT NULL REFERENCES leagues(id),season_code VARCHAR(50) NOT NULL,start_date DATE,end_date DATE,is_current BOOLEAN DEFAULT FALSE,UNIQUE(league_id,season_code));
CREATE TABLE IF NOT EXISTS teams(id BIGSERIAL PRIMARY KEY,sport_id BIGINT NOT NULL REFERENCES sports(id),provider_team_id VARCHAR(100),name VARCHAR(200) NOT NULL,country VARCHAR(100),logo_url TEXT,UNIQUE(sport_id,provider_team_id));
CREATE TABLE IF NOT EXISTS players(id BIGSERIAL PRIMARY KEY,sport_id BIGINT NOT NULL REFERENCES sports(id),provider_player_id VARCHAR(100),name VARCHAR(200) NOT NULL,nationality VARCHAR(100),photo_url TEXT,UNIQUE(sport_id,provider_player_id));
CREATE TABLE IF NOT EXISTS matches(id BIGSERIAL PRIMARY KEY,sport_id BIGINT NOT NULL REFERENCES sports(id),league_id BIGINT REFERENCES leagues(id),season_id BIGINT REFERENCES seasons(id),provider_match_id VARCHAR(100),home_team_id BIGINT REFERENCES teams(id),away_team_id BIGINT REFERENCES teams(id),start_time TIMESTAMPTZ NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'NS',status_detail VARCHAR(100),home_score NUMERIC(8,2),away_score NUMERIC(8,2),venue VARCHAR(200),referee VARCHAR(200),raw_payload JSONB DEFAULT '{}'::jsonb,updated_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(sport_id,provider_match_id));
CREATE TABLE IF NOT EXISTS match_events(id BIGSERIAL PRIMARY KEY,match_id BIGINT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,event_type VARCHAR(100),event_time VARCHAR(50),player_name VARCHAR(200),detail TEXT,payload JSONB DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS match_team_stats(id BIGSERIAL PRIMARY KEY,match_id BIGINT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,team_id BIGINT NOT NULL REFERENCES teams(id),statistics JSONB NOT NULL DEFAULT '{}'::jsonb,updated_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(match_id,team_id));
CREATE TABLE IF NOT EXISTS player_statistics(id BIGSERIAL PRIMARY KEY,match_id BIGINT REFERENCES matches(id) ON DELETE CASCADE,player_id BIGINT REFERENCES players(id),statistics JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS predictions(id BIGSERIAL PRIMARY KEY,match_id BIGINT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,model_version VARCHAR(100) NOT NULL,probabilities JSONB NOT NULL,predicted_result VARCHAR(50),predicted_score JSONB,confidence NUMERIC(6,4),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS prediction_results(id BIGSERIAL PRIMARY KEY,prediction_id BIGINT NOT NULL REFERENCES predictions(id) ON DELETE CASCADE,actual_result VARCHAR(50),actual_score JSONB,evaluated_at TIMESTAMPTZ DEFAULT NOW(),brier_score NUMERIC(10,6),log_loss NUMERIC(10,6));
CREATE TABLE IF NOT EXISTS collection_logs(id BIGSERIAL PRIMARY KEY,provider VARCHAR(50) NOT NULL,endpoint VARCHAR(200),request_count INTEGER DEFAULT 0,status VARCHAR(30) NOT NULL,error_message TEXT,collected_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_matches_start_time ON matches(start_time);
CREATE INDEX IF NOT EXISTS idx_matches_sport_status ON matches(sport_id,status);
CREATE INDEX IF NOT EXISTS idx_events_match ON match_events(match_id);
INSERT INTO sports(code,name) VALUES('football','축구'),('baseball','야구'),('basketball','농구'),('volleyball','배구'),('tennis','테니스'),('hockey','하키'),('american_football','미식축구'),('mma','MMA') ON CONFLICT(code) DO NOTHING;
